// =====================================================================
// THE DIGEST
//
// Design rules, in priority order:
//   1. If there is nothing worth £50+, SEND NOTHING. Silence is the default.
//   2. Never more than three items. Three.
//   3. Every item leads with the pounds, then the single next physical action.
//   4. No dashboards, no charts, no "insights". Just: do this, get that.
//
// A system that pings you constantly is a system you mute, and a muted
// system earns nothing. The restraint IS the feature.
// =====================================================================

const actions = $('Top 3 Actions').all()
  .map(i => i.json)
  .filter(a => a && a.id);      // alwaysOutputData can yield one empty item

const score = $('Load Scoreboard').first().json || {};

if (actions.length === 0) {
  return [{ json: { should_send: false, reason: 'nothing above the value floor' } }];
}

const gbp = n => '£' + Number(n || 0).toLocaleString('en-GB', {
  minimumFractionDigits: 0,
  maximumFractionDigits: 0,
});

const totalOnTable = actions.reduce((s, a) => s + Number(a.annual_value_gbp || 0), 0);
const totalMinutes = actions.reduce((s, a) => s + Number(a.minutes_required || 0), 0);

const lines = [];
lines.push(`<b>${gbp(totalOnTable)} on the table this week</b>`);
lines.push(`<i>${totalMinutes} minutes of work, total.</i>`);
lines.push('');

actions.forEach((a, idx) => {
  const value = Number(a.annual_value_gbp || 0);
  const isDeadline = a.due_date != null;

  let header = `<b>${idx + 1}. ${escapeHtml(a.title)}</b>`;
  lines.push(header);

  const meta = [];
  if (value > 0) meta.push(`${gbp(value)}/yr`);
  meta.push(`${a.minutes_required} min`);
  if (isDeadline) {
    const days = Math.ceil((new Date(a.due_date) - new Date()) / 86400000);
    meta.push(days > 0 ? `⏳ ${days} days left` : '⏳ OVERDUE');
  }
  lines.push(`   <i>${meta.join(' · ')} · ref #${a.id}</i>`);

  if (a.detail) {
    // Keep it short — long blocks are the thing that makes people stop reading.
    const detail = String(a.detail).replace(/\s+/g, ' ').trim();
    lines.push(`   ${escapeHtml(detail.length > 400 ? detail.slice(0, 397) + '…' : detail)}`);
  }

  if (a.action_url) {
    lines.push(`   <a href="${escapeHtml(a.action_url)}">→ Do it here</a>`);
  }

  lines.push('');
});

// ---- the scoreboard footer ----
// This exists purely for motivation. Watching the number go up is what
// keeps you opening the message in month seven.
const banked = Number(score.total_one_off_gbp || 0) + Number(score.total_annual_gbp || 0);
if (banked > 0) {
  lines.push('———');
  lines.push(`<b>Banked so far: ${gbp(banked)}</b> across ${score.wins_count} wins.`);
}

const recurring = Number(score.recurring_annual_gbp || 0);
if (recurring > 0) {
  lines.push(`<i>Watching ${gbp(recurring)}/yr of recurring payments.</i>`);
}

const openCount = Number(score.open_count || 0);
if (openCount > actions.length) {
  lines.push(`<i>${openCount - actions.length} smaller items held back — they'll surface as these clear.</i>`);
}

// Closing the loop: replying "done 42" banks the win and clears the item.
lines.push('');
lines.push('<i>Reply "done 42" when you finish one, or "skip 42" to bin it.</i>');

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

return [{
  json: {
    should_send: true,
    message: lines.join('\n'),
    action_ids: actions.map(a => a.id),
    total_on_table: totalOnTable,
  }
}];

